$(document).on("WebPlayerSeIniciaSistema",function(){var control=Ciel.MPC.WebPlayer.Utilidad.ObtenerControl("PasoTres","btnCargarDocumentos");if(!control||!control.DivContenedor){return;}
var content=control.DivContenedor;if(!content){console.error('No se encontro un contenedor de elementos en el boton');return;}
var rutaImagen=Ciel.MPC.WebPlayer.RutaRecursos+"img/PasoTres/btnDownload.svg"
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagen);var divContentImg=document.createElement("div");divContentImg.append(imgCola);divContentImg.classList.add('contentImgDescarga');content.prepend(divContentImg);});